    # Raw DDL (not op.create_table): SQLAlchemy core has no first-class
    # pgvector type without the pgvector-python dialect plugin. The ORM
    # model (app/models/copilot_doc.py) deliberately maps `embedding` as
    # Text (nullable) so SELECT * round-trips without erroring, but the
    # real column is a native `vector(1536) NOT NULL` — writes go through
    # raw SQL in app/services/agents/doc_index.py. Preserves the exact
    # schema the old chain's migration 049 created.
    op.execute("""
        CREATE TABLE copilot_doc_chunks (
            id           BIGSERIAL PRIMARY KEY,
            source_path  TEXT NOT NULL,
            chunk_index  INTEGER NOT NULL,
            content      TEXT NOT NULL,
            embedding    vector(1536) NOT NULL,
            metadata     JSONB NOT NULL DEFAULT '{}'::jsonb,
            indexed_at   TIMESTAMPTZ NOT NULL DEFAULT now()
        )
        """)
    op.execute(
        "CREATE UNIQUE INDEX copilot_doc_chunks_source_chunk_uq "
        "ON copilot_doc_chunks (source_path, chunk_index)"
    )
    # HNSW ANN index, cosine distance — sub-10ms top-k=4 on ~1k chunks
    # (pgvector defaults: m=16, ef_construction=64).
    op.execute(
        "CREATE INDEX copilot_doc_chunks_embedding_hnsw "
        "ON copilot_doc_chunks USING hnsw (embedding vector_cosine_ops)"
    )
